## Backend starter (Express + SQLite)

```js
// server.js
import express from "express";
import cors from "cors";
import { nanoid } from "nanoid";
import Database from "better-sqlite3";

const db = new Database("whispr.db");
const app = express();
app.use(cors());
app.use(express.json());

db.exec(`
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  device_token TEXT UNIQUE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS posts (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  room TEXT DEFAULT 'global',
  content TEXT,
  alias TEXT,
  expires_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS reactions (
  id TEXT PRIMARY KEY,
  post_id TEXT,
  user_id TEXT,
  type TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS reports (
  id TEXT PRIMARY KEY,
  post_id TEXT,
  user_id TEXT,
  reason TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
`);

const adjectives = ["quiet", "brave", "tiny", "cosmic", "hidden", "gentle"];
const animals = ["panda", "fox", "owl", "wolf", "cat", "raven"];
const alias = () =>
  `${adjectives[Math.floor(Math.random()*adjectives.length)]}-` +
  `${animals[Math.floor(Math.random()*animals.length)]}-` +
  `${Math.floor(Math.random()*1000)}`;

// Anonymous session
app.post("/api/session", (req, res) => {
  const token = req.body.device_token || nanoid();
  let user = db.prepare("SELECT * FROM users WHERE device_token = ?").get(token);
  if (!user) {
    const id = nanoid();
    db.prepare("INSERT INTO users (id, device_token) VALUES (?, ?)").run(id, token);
    user = { id, device_token: token };
  }
  res.json({ user_id: user.id, device_token: token });
});

// Create post
app.post("/api/posts", (req, res) => {
  const { user_id, content, room = "global", ttl_hours = 24 } = req.body;
  if (!content || content.length > 280) return res.status(400).json({ error: "Invalid content" });
  const id = nanoid();
  const expires = new Date(Date.now() + ttl_hours * 3600 * 1000).toISOString();
  db.prepare(
    "INSERT INTO posts (id, user_id, room, content, alias, expires_at) VALUES (?, ?, ?, ?, ?, ?)"
  ).run(id, user_id, room, content, alias(), expires);
  res.json({ id });
});

// Feed
app.get("/api/posts", (req, res) => {
  const room = req.query.room || "global";
  const limit = Math.min(parseInt(req.query.limit || "50"), 100);
  const rows = db.prepare(`
    SELECT p.*, 
      (SELECT COUNT(*) FROM reactions r WHERE r.post_id = p.id) AS reaction_count
    FROM posts p
    WHERE p.room = ? AND (p.expires_at IS NULL OR p.expires_at > CURRENT_TIMESTAMP)
    ORDER BY p.created_at DESC
    LIMIT ?
  `).all(room, limit);
  res.json(rows);
});

// React
app.post("/api/posts/:id/react", (req, res) => {
  const { user_id, type } = req.body;
  const existing = db.prepare(
    "SELECT * FROM reactions WHERE post_id = ? AND user_id = ? AND type = ?"
  ).get(req.params.id, user_id, type);
  if (existing) {
    db.prepare("DELETE FROM reactions WHERE id = ?").run(existing.id);
    return res.json({ toggled: false });
  }
  db.prepare("INSERT INTO reactions (id, post_id, user_id, type) VALUES (?, ?, ?, ?)")
    .run(nanoid(), req.params.id, user_id, type);
  res.json({ toggled: true });
});

// Report
app.post("/api/posts/:id/report", (req, res) => {
  const { user_id, reason } = req.body;
  db.prepare("INSERT INTO reports (id, post_id, user_id, reason) VALUES (?, ?, ?, ?)")
    .run(nanoid(), req.params.id, user_id, reason);
  res.json({ ok: true });
});

app.listen(3000, () => console.log("Whispr API on :3000"));
```

